-- places/upsert-province
-- Inserts or updates one province by its code. Used only by the places import.
--
-- Parameters, with the example values used to render this file:
--   $1 = 3
--   $2 = "bagmati"
--   $3 = "Bagmati"
--   $4 = "बागमती"
--   $5 = "{\"type\":\"Polygon\",\"coordinates\":[[[85.3,27.7],[85.31,27.7],[85.31,27.71],[85.3,27.7]]]}"
--   $6 = "bagmati"
--   $7 = "Bagmati"
--   $8 = "बागमती"
--   $9 = "{\"type\":\"Polygon\",\"coordinates\":[[[85.3,27.7],[85.31,27.7],[85.31,27.71],[85.3,27.7]]]}"
--
-- Generated by `pnpm db:queries` from lib/db/queries/places.ts. Do not edit by hand.

insert into "provinces" ("id", "code", "slug", "name_en", "name_np", "geom", "created_at", "updated_at")
values (default, $1, $2, $3, $4, ST_Multi(ST_CollectionExtract(ST_UnaryUnion(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON($5), 4326))), 3)), default, default)
on conflict ("code")
do update
set "slug" = $6, "name_en" = $7, "name_np" = $8, "geom" = ST_Multi(ST_CollectionExtract(ST_UnaryUnion(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON($9), 4326))), 3)), "updated_at" = now()
returning "id";
